    rows_above = max(rows4)<min(sixrows)
    vertical = rows_above  # object above 6 -> mirror vertically (downward)
    if vertical:
        k=max(rows4)
        for i,row in enumerate(g[:k+1]):
            for j,x in enumerate(row):
                if x: out[i][j]=x
        for i,row in enumerate(reversed(g[:k+1])):
            ti=k+1+i
            for j,x in enumerate(row):
                if x and ti<h: out[ti][j]=x
