def symCombo(gi, go):
    # does output 4-mask have mirror symmetry; which axis?
    om=[r[:] for r in gi]
    for i in range(len(om)):
        for j in range(len(om[0])):
            if om[i][j]==4: om[i][j]=1
    o4=[r[:] for r in go]
    for i in range(len(o4)):
        for j in range(len(o4[0])):
            if o4[i][j]==4: o4[i][j]=1
    H=len(o4); W=len(o4[0])
    v_sym=all(o4[i][j]==o4[H-1-i][j] for i in range(H) for j in range(W))
    h_sym=all(o4[i][j]==o4[i][W-1-j] for i in range(H) for j in range(W))
    return v_sym, h_sym
